referenceFixTemplate:
with open("通讯录.txt", "w", encoding="utf-8") as 档案:
    档案.write("咪爱|{p1}\n大肥鱼|{p2}\n")

通讯录 = {}
with open("通讯录.txt", encoding="utf-8") as 档案:
    for 行 in 档案:
        行 = 行.strip()
        if not 行:
            continue
        名字, 号码 = 行.split("|", 1)
        通讯录[名字] = 号码

for 名字, 号码 in 通讯录.items():
    print(f"{名字} 的号码是 {号码}")
